parameters.text:
=Analiza estos datos reales del inventario SAGER y responde solo en JSON estricto.

Datos recibidos desde la API Laravel:
{{ JSON.stringify($json) }}

parameters.jsCode:
const analytics = $('HTTP Request - Consultar API').first().json;
const raw = $json.output ?? $json.text ?? $json.response ?? $json.message ?? $json;

function buildDeterministicMessage(data) {
  const alertas = Array.isArray(data.alertas_criticas) ? data.alertas_criticas : [];
  const valor = Number(data.valor_total_inventario || 0).toFixed(2);

  if (alertas.length > 0) {
    const productos = alertas
      .map((producto) => `${producto.nombre} (${producto.stock} unidades)`)
      .join(', ');

    return {
      mensaje: `Inventario valorizado en Bs ${valor}. Diagnostico critico: stock bajo en ${productos}. Reposicion prioritaria requerida.`,
      prioridad: 'critico',
    };
  }

  return {
    mensaje: `Inventario valorizado en Bs ${valor}. Diagnostico informativo: no existen productos con stock critico.`,
    prioridad: 'info',
  };
}

let payload = raw;

if (typeof payload === 'string') {
  payload = payload
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  try {
    payload = JSON.parse(payload);
  } catch (error) {
    payload = null;
  }
}

if (!payload || typeof payload !== 'object' || !payload.mensaje || !['critico', 'info'].includes(payload.prioridad)) {
  payload = buildDeterministicMessage(analytics);
}

return [
  {
    json: {
      mensaje: payload.mensaje,
      prioridad: payload.prioridad,
    },
  },
];
